// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 betLimit) public {
        // Ensure betLimit is reasonable (nonzero and not too large)
        vm.assume(betLimit > 0 && betLimit < address(this).balance);

        // Open to public and set bet limit
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(betLimit);

        // Fund an account to make a wager
        address player = address(0x1234);
        vm.deal(player, betLimit);

        // Player wagers
        vm.prank(player, player);
        c.wager{value: betLimit}();

        // General rule: ethBalance should be at least the wager amount
        assertTrue(c.ethBalance() >= betLimit);
    }
}

